"""Generate defaults.go from the scoreboard's Rule.java.

    git -C scoreboard show v2025.10:src/com/carolinarollergirls/scoreboard/rules/Rule.java > Rule.java
    python3 legacy/gen_defaults.py Rule.java v2025.10 > legacy/defaults.go && gofmt -w legacy/defaults.go
"""
import re
import sys

path, version = sys.argv[1], sys.argv[2]
src = open(path).read()
src = re.sub(r'"\s*\+\s*"', '', src)  # join "a" + "b" string concatenations
src = re.sub(r'\s+', ' ', src)

rules = []
for m in re.finditer(r'new (\w+)Rule\(\s*"([^"]+)",\s*"[^"]*",\s*("[^"]*"|[\w.]+)', src):
    kind, name, val = m.group(1), m.group(2), m.group(3).strip('"')
    if kind == 'Boolean':
        val = val.lower()
    rules.append((name, kind.lower(), val))
if not rules:
    sys.exit('no rules found')

var = 'defaults' + re.sub(r'\W', '_', version.lstrip('v'))
print(f'// Code generated by legacy/gen_defaults.py from Rule.java at {version}; DO NOT EDIT.')
print()
print('package legacy')
print()
print(f'var {var} = map[string]ruleDef{{')
for name, kind, val in rules:
    print(f'\t"{name}": {{"{kind}", "{val}"}},')
print('}')
